#!/usr/bin/env python3
"""Regenerates src/features/brands/data.ts from scripts/brand-icons.json (written by fetch-brand-icons.mjs).
Order of preference per merchant: sharp site icon, Simple Icons glyph (CC0), colour monogram.
Usage: python3 scripts/gen-brand-data.py <path to an unpacked simple-icons package>"""
import json, re, os, sys
SI = sys.argv[1].rstrip('/') + '/'
meta = {d['slug']: d for d in json.load(open(SI + 'data/simple-icons.json'))}
def glyph(slug):
    f = SI + f'icons/{slug}.svg'
    if not os.path.exists(f): return None
    return {'path': re.search(r'<path d="([^"]+)"', open(f).read()).group(1), 'hex': meta[slug]['hex']}
res = json.load(open('scripts/brand-icons.json'))
SIMAP = {'McDonald’s':'mcdonalds','KFC':'kfc','Paytm':'paytm','Google Pay':'googlepay','Airtel':'airtel','Dropbox':'dropbox','Google Play':'googleplay','BigBasket':'bigbasket','Jio':'jio','Netflix':'netflix','Zoom':'zoom','Zerodha':'zerodha','Zoho':'zoho','HDFC Bank':'hdfcbank','ICICI Bank':'icicibank','Axis Bank':'axisbank','Bata':'bata'}
EXTRA = [('Uber Eats','ubereats',[]),('YouTube Music','youtubemusic',[]),('Lyft','lyft',[]),('Razorpay','razorpay',[]),('PhonePe','phonepe',['phone pe'])]
MONO = {'Subway':'008C15','Samsung':'1428A0','BluSmart':'0B5FFF','Lifestyle':'E31E24','Digit Insurance':'F58220','Spencer’s':'E31E24','Pantaloons':'D62027','Tata Power':'0B5CAB','Ajio':'2C4152','Meesho':'570D48','Snapdeal':'E40046','Barbeque Nation':'8B1A1A','Licious':'D6203A','BYJU’S':'813588','Dream11':'D41F2D','SBI':'22409A','Kotak':'ED1C24','Yes Bank':'00518F','IDFC FIRST Bank':'9D1D27','Punjab National Bank':'A20E37','Bank of Baroda':'F58220','Union Bank':'004F9F','RBL Bank':'21409A','Groww':'00B386','IRCTC':'1F4E9E','redBus':'D63941','JioCinema':'D9187B','JioSaavn':'2BC5B4','Namma Yatri':'FFD23F','Dunzo':'00D290','Blinkit':'F8CB46','Zepto':'5E2B97','Flipkart':'2874F0','Domino’s':'006491','Dineout':'E2231A','Vijay Sales':'D5232A','More Retail':'EF7D00','Urban Ladder':'F26722','Reliance Digital':'E42529','H&M':'E50010','Westside':'1A1A1A','OnePlus':'EB0028','boAt':'1A1A1A','Tira':'1A1A1A','Sugar Cosmetics':'1A1A1A','Meru Cabs':'F9A01B','Akasa Air':'FF6A13','HPCL':'0A4DA2','Google One':'4285F4','BHIM':'F26522','MobiKwik':'2B8CFF','ICICI Prudential':'B02A30','Bajaj Finserv':'0066B3','Navi':'4B3FE0','KreditBee':'F6A800','Tata Play':'5A2A82','Dish TV':'F26F21','Hathway':'E31E24','Adani Electricity':'0B74B8','Apollo Pharmacy':'00A0A0','Netmeds':'00A859','DTDC':'E31E24','Blue Dart':'1E3C8C','Faasos':'E23744','Chaayos':'6B3F27','Blue Tokai':'1C1C1C','Amazon':'FF9900','Ola':'1C1C1C','CRED':'1A1A1A','Cars24':'4F4DEC','Mamaearth':'00A19A','Wakefit':'0F3C6E','Pepperfry':'F26B21','FirstCry':'F26522','Cleartrip':'F26522','EaseMyTrip':'00A0E3','Yatra':'E5002B','inDrive':'C2F200','Agoda':'5C2D91','Indian Oil':'F37021','Bharat Petroleum':'FFD200','Disney+ Hotstar':'0C1B4B','LinkedIn':'0A66C2','OneCard':'1A1A1A','Angel One':'E4572E','INDmoney':'1A1A1A','LIC':'0067AC','SBI Life':'22409A','ClearTax':'F26B21','ACT Fibernet':'E31E24','Mahanagar Gas':'0072BC','PharmEasy':'10847E','Magicpin':'E91E63','JioMart':'0078AD','Third Wave Coffee':'1C1C1C','Behrouz Biryani':'1C1C1C','Cafe Coffee Day':'B1372E'}
PALETTE = ['C2501A', '3F7CAC', 'B83A5B', '0E7C70', '6C5B9E', 'A0527C', '2F7FA8', '5B6FB0', '8C5A3C', '212934']
DARK_TEXT = {'Namma Yatri','Blinkit','inDrive','Bharat Petroleum','KreditBee'}
def lum(h):
    r,g,b=[int(h[i:i+2],16)/255 for i in (0,2,4)]; return .2126*r+.7152*g+.0722*b
js = lambda v: json.dumps(v, ensure_ascii=False)
out = ["// Generated by scripts/gen-brand-data.py from scripts/brand-icons.json. Pictures are each merchant's own site icon, fetched\n// once at build time (sources of at least 128 px only) and bundled; glyphs are Simple Icons (CC0). Brand names and marks belong to\n// their owners and are shown only to help recognise a merchant. Do not edit by hand.\nimport type { ImageSourcePropType } from 'react-native';\nexport interface Brand { name: string; aliases: string[]; hex: string; dark: boolean; path?: string; img?: ImageSourcePropType }\nexport const BRANDS: Brand[] = ["]
RISKY = {'idea','boat','sugar','apollo','digit','kite','meta','pw','bob','fk','district','eternal','mi store'}
n_img = n_gl = n_mo = 0
names = set()
for x in res:
    al = [a for a in x['aliases'].split(',') if a and a not in RISKY]
    names.add(x['name'])
    if x.get('file'):
        h = x.get('hex', '#3A4452'); n_img += 1
        out.append(f"  {{ name: {js(x['name'])}, aliases: {js(al)}, hex: {js(h)}, dark: {str(lum(h[1:])>0.62).lower()}, img: require('../../../assets/brands/{x['file']}') }},")
    elif x['name'] in SIMAP and glyph(SIMAP[x['name']]):
        g = glyph(SIMAP[x['name']]); n_gl += 1
        out.append(f"  {{ name: {js(x['name'])}, aliases: {js(al)}, hex: '#{g['hex']}', dark: {str(lum(g['hex'])>0.62).lower()}, path: {js(g['path'])} }},")
    else:
        h = MONO.get(x['name']) or PALETTE[sum(map(ord, x['name'])) % len(PALETTE)]; n_mo += 1
        d = x['name'] in DARK_TEXT or lum(h) > 0.62
        out.append(f"  {{ name: {js(x['name'])}, aliases: {js(al)}, hex: '#{h}', dark: {str(d).lower()} }},")
for n, slug, al in EXTRA:
    g = glyph(slug)
    if g and n not in names:
        out.append(f"  {{ name: {js(n)}, aliases: {js(al)}, hex: '#{g['hex']}', dark: {str(lum(g['hex'])>0.62).lower()}, path: {js(g['path'])} }},"); n_gl += 1
out.append("];\n")
open('src/features/brands/data.ts', 'w').write("\n".join(out))
print('images', n_img, 'glyphs', n_gl, 'monograms', n_mo)
